def design(feats):
    import numpy as np
    from scipy import stats
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float)
    n, p = X.shape; ids = list(feats.ids)
    strata = sorted(set(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.array([s == t for s in feats.stratum], float) for t in strata[1:]])

    def ll(Z):
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))

    def mat(cols, prods=()):
        return np.column_stack([S] + [X[:, j] for j in cols] + [X[:, a] * X[:, b] for a, b in prods])

    R = np.corrcoef(X, rowvar=False)
    sel = []; base = ll(mat(sel))
    while len(sel) < MAX_DRIVERS:
        alpha = (0.5 if not sel else 0.05) / p
        best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            l = ll(mat(sel + [j])); pv = stats.chi2.sf(2 * (l - base), 1)
            if best is None or pv < best[0]: best = (pv, j, l)
        if best is None or best[0] > alpha: break
        sel.append(best[1]); base = best[2]
    changed = True
    while changed and len(sel) > 1:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (base - ll(mat(rest))), 1) > 0.05 / p:
                sel = rest; base = ll(mat(sel)); changed = True; break
    prods = []; npair = p * (p + 1) / 2; cands = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = sorted(set(sel) | {a, b})
            l0 = ll(mat(mains)); l1 = ll(mat(mains, [(a, b)]))
            pv = stats.chi2.sf(2 * (l1 - l0), 1)
            if pv < 0.01 / npair: cands.append((pv, a, b))
    cands.sort()
    for pv, a, b in cands[:2]:
        prods.append((a, b))
    drivers = []
    for pv, a, b in cands[:2]:
        for j in (a, b):
            if j not in drivers: drivers.append(j)
    drivers = sel + [j for j in drivers if j not in sel]
    cols = sorted(set(sel) | {j for ab in prods for j in ab})
    return Design(drivers=tuple(ids[j] for j in drivers[:MAX_DRIVERS]),
                  columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

